from copy import deepcopy
def set_status(document, expected_version, status):
    version = document["version"]
    if type(version) is not int or version < 0 or type(expected_version) is not int or expected_version < 0:
        raise ValueError("Versions must be nonnegative integers")
    if not isinstance(status, str) or not status.strip():
        raise ValueError("Status must be nonblank text")
    result = deepcopy(document)
    if version != expected_version:
        return {"applied":False,"document":result}
    result["status"] = status
    result["version"] += 1
    return {"applied":True,"document":result}
document = {"asset_id":"P1","version":4,"status":"monitor","notes":["keep"]}
print(set_status(document, 4, "inspect")["document"]["version"])

