def indexed_readings(documents, site, minimum):
    index = {}
    for document in documents:
        index.setdefault(document["site"], []).append(document)
    candidates = index.get(site, [])
    matches = [deepcopy(row) for row in candidates if row["temperature"] >= minimum]
    return {"candidates":len(candidates), "matches":matches}
