def whole(value):
    return type(value) is int and value >= 0

def text(value):
    return isinstance(value, str) and bool(value.strip())

def read_bucket(rows, partition, start, end, limit):
    if not isinstance(rows,list) or not isinstance(partition,dict) or set(partition)!={"tenant","asset","day"} or not all(text(v) for v in partition.values()) or not all(whole(v) for v in (start,end,limit)) or start>end:
        raise ValueError("Invalid bucket request")
    seen=set()
    selected=[]
    for row in rows:
        if not isinstance(row,dict) or not text(row.get("id")) or not whole(row.get("time")) or not all(text(row.get(k)) for k in partition):
            raise ValueError("Invalid event")
        if row["id"] in seen: raise ValueError("Event IDs must be unique")
        seen.add(row["id"])
        if all(row[k]==v for k,v in partition.items()) and start<=row["time"]<end:
            selected.append(row)
    selected.sort(key=lambda r:(r["time"],r["id"]))
    return [row["id"] for row in selected[:limit]]

