def session_replica(replicas, minimum):
    if not isinstance(replicas,list) or not whole(minimum): raise ValueError("Invalid session floor")
    candidates=[]
    seen=set()
    for r in replicas:
        if not isinstance(r,dict) or not text(r.get("id")) or not whole(r.get("version")) or type(r.get("reachable")) is not bool or r["id"] in seen:
            raise ValueError("Invalid replica observation")
        seen.add(r["id"])
        if r["reachable"] and r["version"]>=minimum: candidates.append(r)
    candidates.sort(key=lambda r:(-r["version"],r["id"]))
    return candidates[0]["id"] if candidates else "wait"

