def reserve(current, request):
    if not isinstance(current,dict) or not isinstance(request,dict) or not text(current.get("id")) or not text(request.get("id")) or not all(whole(current.get(k)) for k in ("version","units")) or not whole(request.get("expected_version")) or not whole(request.get("amount")) or request["amount"]==0:
        raise ValueError("Invalid reservation")
    accepted = (current["id"]==request["id"] and
                current["version"]==request["expected_version"] and
                current["units"]>=request["amount"])
    result = dict(current)
    if accepted:
        result["units"] -= request["amount"]
        result["version"] += 1
    return {"accepted":accepted,"record":result}

