def whole(value):
    return type(value) is int and value >= 0

def text(value):
    return isinstance(value, str) and bool(value.strip())

def merge_counter(left, right):
    for state in (left,right):
        if not isinstance(state,dict) or not all(text(k) and whole(v) for k,v in state.items()):
            raise ValueError("Invalid grow-only components")
    merged = {key:max(left.get(key,0),right.get(key,0)) for key in sorted(set(left)|set(right))}
    return {"components":merged,"total":sum(merged.values())}

