def whole(value):
    return type(value) is int and value >= 0

def text(value):
    return isinstance(value, str) and bool(value.strip())

def project_jobs(state, events):
    def clean(row):
        if not isinstance(row,dict) or not text(row.get("id")) or not text(row.get("asset")) or not whole(row.get("version")) or row.get("status") not in ("open","done","deleted"):
            raise ValueError("Invalid job image")
        return {key:row[key] for key in ("id","asset","version","status")}
    if not isinstance(state,list) or not isinstance(events,list): raise ValueError("Lists required")
    observed={}
    for row in state + events:
        image=clean(row)
        key=(image["id"],image["version"])
        if key in observed and observed[key]!=image:
            raise ValueError("Conflicting equal version in supplied images")
        observed[key]=image
    current={}
    for row in state:
        image=clean(row)
        if image["id"] in current: raise ValueError("Duplicate stored identity")
        current[image["id"]]=image
    for row in events:
        image=clean(row); old=current.get(image["id"])
        if old is None or image["version"]>old["version"]:
            current[image["id"]]=image
        elif image["version"]==old["version"] and image!=old:
            raise ValueError("Conflicting equal version")
    counts={}
    for image in current.values():
        if image["status"]=="open": counts[image["asset"]]=counts.get(image["asset"],0)+1
    return {"state":[current[k] for k in sorted(current)],"open_by_asset":dict(sorted(counts.items()))}

