import math

def adapt_readings(documents):
    if not isinstance(documents,list): raise ValueError("Documents must be a list")
    result=[]
    for doc in documents:
        if not isinstance(doc,dict) or not text(doc.get("id")) or type(doc.get("schema")) is not int:
            raise ValueError("Invalid document envelope")
        if doc["schema"]==1:
            value,unit=doc.get("temp_c"),"C"
        elif doc["schema"]==2:
            temperature=doc.get("temperature")
            if not isinstance(temperature,dict): raise ValueError("Missing temperature record")
            value,unit=temperature.get("value"),temperature.get("unit")
        else:
            raise ValueError("Unsupported schema")
        if type(value) not in (int,float) or not math.isfinite(value) or unit not in ("C","F"):
            raise ValueError("Invalid temperature")
        celsius=(value-32)*5/9 if unit=="F" else value
        result.append({"id":doc["id"],"schema":2,"temperature":{"value":round(celsius,3),"unit":"C"}})
    return result

