def whole(value):
    return type(value) is int and value >= 0

def text(value):
    return isinstance(value, str) and bool(value.strip())

def restore_inventory(snapshot, events, target):
    if not isinstance(snapshot,dict) or not whole(snapshot.get("seq")) or not isinstance(snapshot.get("state"),dict) or not isinstance(events,list) or not whole(target) or target<snapshot["seq"]:
        raise ValueError("Invalid restore request")
    state=dict(snapshot["state"])
    if not all(text(k) and whole(v) for k,v in state.items()): raise ValueError("Invalid snapshot state")
    seen=set(); selected=[]
    for event in events:
        if not isinstance(event,dict) or not whole(event.get("seq")) or not text(event.get("id")) or not whole(event.get("units")) or event["seq"] in seen:
            raise ValueError("Invalid log record")
        seen.add(event["seq"])
        if snapshot["seq"]<event["seq"]<=target: selected.append(event)
    selected.sort(key=lambda e:e["seq"])
    if [e["seq"] for e in selected]!=list(range(snapshot["seq"]+1,target+1)):
        raise ValueError("Required retained history is missing")
    for event in selected: state[event["id"]]=event["units"]
    return {"seq":target,"state":state}

