def whole(value):
    return type(value) is int and value >= 0

def text(value):
    return isinstance(value, str) and bool(value.strip())

import math

def serving_vector(record, request, fields):
    if not isinstance(record,dict) or not isinstance(request,dict) or not all(text(request.get(k)) for k in ("tenant","asset","feature_version")) or not all(whole(request.get(k)) for k in ("as_of","max_age")) or not isinstance(fields,list) or not fields or not all(text(k) for k in fields) or len(set(fields))!=len(fields):
        raise ValueError("Invalid serving request")
    fallback={"route":"fallback","vector":[]}
    if any(record.get(k)!=request[k] for k in ("tenant","asset","feature_version")):
        return fallback
    event,available=record.get("event_time"),record.get("available_time")
    if not whole(event) or not whole(available) or not event<=available<=request["as_of"] or request["as_of"]-event>request["max_age"]:
        return fallback
    features=record.get("features")
    if not isinstance(features,dict) or any(type(features.get(k)) not in (int,float) or not math.isfinite(features[k]) for k in fields):
        return fallback
    return {"route":"predict","vector":[features[k] for k in fields]}

