def reachable(graph, start, max_depth):
    from collections import deque
    neighbours={}
    for e in graph['edges']:
        if e['type']=='DEPENDS_ON': neighbours.setdefault(e['source'],[]).append(e['target'])
    visited={start}
    queue=deque([(start,0)])
    while queue:
        current,depth=queue.popleft()
        if depth>=max_depth: continue
        for target in neighbours.get(current,[]):
            if target not in visited:
                visited.add(target)
                queue.append((target,depth+1))
    return sorted(visited-{start})

print(reachable({"nodes": [{"id": "P7", "kind": "Asset"}, {"id": "S1", "kind": "Asset"}, {"id": "S2", "kind": "Asset"}, {"id": "S3", "kind": "Asset"}], "edges": [{"id": "a", "source": "P7", "target": "S1", "type": "DEPENDS_ON"}, {"id": "b", "source": "S1", "target": "S2", "type": "DEPENDS_ON"}, {"id": "c", "source": "S2", "target": "P7", "type": "DEPENDS_ON"}, {"id": "d", "source": "S2", "target": "S3", "type": "DEPENDS_ON"}]}, 'P7', 2))

def shortest_cost(graph, start, target):
    import heapq
    neighbours={}
    for e in graph['edges']:
        if e['type']!='ROUTE': continue
        cost=e.get('minutes')
        if isinstance(cost,bool) or not isinstance(cost,(int,float)) or not __import__('math').isfinite(cost) or cost<0: raise ValueError('Costs must be finite and nonnegative')
        neighbours.setdefault(e['source'],[]).append((e['target'],cost))
    best={start:0}
    heap=[(0,start)]
    while heap:
        cost,current=heapq.heappop(heap)
        if cost!=best[current]: continue
        if current==target: return cost
        for nxt,weight in neighbours.get(current,[]):
            candidate=cost+weight
            if candidate<best.get(nxt,float('inf')):
                best[nxt]=candidate
                heapq.heappush(heap,(candidate,nxt))
    return None

