def context_docs(graph, start, tenant, as_of, max_depth):
    from collections import deque
    allowed={n['id']:n for n in graph['nodes'] if n.get('tenant')==tenant}
    if start not in allowed or allowed[start]['kind']!='Asset':
        return []
    edges=[e for e in graph['edges'] if e['source'] in allowed and e['target'] in allowed]
    seen={start}
    pending=deque([(start,0)])
    while pending:
        node,depth=pending.popleft()
        if depth >= max_depth:
            continue
        for e in edges:
            if e['type']=='DEPENDS_ON' and e['source']==node and allowed[e['target']]['kind']=='Asset' and e['target'] not in seen:
                seen.add(e['target'])
                pending.append((e['target'],depth+1))
    docs={e['target'] for e in edges if e['type']=='HAS_MANUAL' and e['source'] in seen}
    return sorted(id for id in docs if allowed[id]['kind']=='Document' and allowed[id]['available_at'] <= as_of)

