import numpy as np
def aligned(a, b):
    a, b = np.asarray(a, dtype=float), np.asarray(b, dtype=float)
    if a.ndim != 1 or b.shape != a.shape or a.size == 0:
        raise ValueError("Use aligned nonempty one-dimensional arrays")
    if not np.isfinite(a).all() or not np.isfinite(b).all():
        raise ValueError("Values must be finite")
    return a, b

def alert_report(scores, labels, threshold):
    scores, labels = aligned(scores, labels)
    if np.any((scores < 0) | (scores > 1)) or not np.isin(labels, [0,1]).all():
        raise ValueError("Use probability scores and binary labels")
    if not np.isfinite(threshold) or not 0 <= threshold <= 1:
        raise ValueError("Threshold must be in [0,1]")
    selected = scores >= threshold
    tp = int(np.sum(selected & (labels == 1)))
    alerts, positives = int(selected.sum()), int(labels.sum())
    return alerts, tp / alerts if alerts else None, tp / positives if positives else None

