import numpy as np
def aligned(a, b):
    a, b = np.asarray(a, dtype=float), np.asarray(b, dtype=float)
    if a.ndim != 1 or b.shape != a.shape or a.size == 0:
        raise ValueError("Use aligned nonempty one-dimensional arrays")
    if not np.isfinite(a).all() or not np.isfinite(b).all():
        raise ValueError("Values must be finite")
    return a, b

def paired_bootstrap(baseline, candidate, draws):
    old, new = aligned(baseline, candidate)
    if np.any(old < 0) or np.any(new < 0):
        raise ValueError("Losses must be nonnegative")
    indices = np.asarray(draws)
    if indices.ndim != 2 or indices.shape[0] == 0 or indices.shape[1] != old.size:
        raise ValueError("Each draw must contain n indices")
    if not np.issubdtype(indices.dtype, np.integer) or np.any(indices < 0) or np.any(indices >= old.size):
        raise ValueError("Indices must be integers inside the sample")
    gain = old - new
    return gain[indices].mean(axis=1)

