import numpy as np
def nested_report(inner, outer):
    inner, outer = np.asarray(inner,dtype=float), np.asarray(outer,dtype=float)
    if inner.ndim != 2 or outer.shape != inner.shape or 0 in inner.shape:
        raise ValueError("Use matching nonempty fold-by-candidate tables")
    if not np.isfinite(inner).all() or not np.isfinite(outer).all() or np.any(inner < 0) or np.any(outer < 0):
        raise ValueError("Use finite nonnegative losses")
    choices = inner.argmin(axis=1)
    selected = outer[np.arange(inner.shape[0]), choices]
    return choices.tolist(), selected.tolist(), float(selected.mean())

