import numpy as np
def review_queue(records, threshold):
    if not np.isfinite(threshold) or not .5 < threshold <= 1:
        raise ValueError("Threshold must be above .5 and at most 1")
    seen, queue = set(), []
    for row in records:
        identifier = row['id']
        if not isinstance(identifier,str) or not identifier.strip() or identifier in seen:
            raise ValueError("IDs must be nonempty and unique")
        seen.add(identifier)
        if row['split'] not in ('development','test') or row['label'] not in (0,1):
            raise ValueError("Invalid split or label")
        score = row['p']
        if not np.isfinite(score) or not 0 <= score <= 1:
            raise ValueError("Invalid positive score")
        disagreement = score if row['label'] == 0 else 1-score
        if row['split'] == 'development' and disagreement >= threshold:
            queue.append(identifier)
    return queue

