import numpy as np

def review(labels, decisions, arrivals, capacities, miss_limit, backlog_limit):
    y, d = np.asarray(labels), np.asarray(decisions)
    a, c = np.asarray(arrivals, dtype=float), np.asarray(capacities, dtype=float)
    limits = np.asarray([miss_limit, backlog_limit], dtype=float)
    if y.ndim != 1 or d.shape != y.shape or not np.isin(y,[0,1]).all() or not np.isin(d,[0,1]).all():
        raise ValueError("Invalid fault fixture")
    if a.ndim != 1 or c.shape != a.shape:
        raise ValueError("Invalid load fixture")
    for x in (a,c,limits):
        if not np.isfinite(x).all() or (x < 0).any() or (x != np.floor(x)).any():
            raise ValueError("Counts and limits must be finite nonnegative integers")
    missed = int((y*(1-d)).sum())
    waiting = peak = 0
    for incoming, slots in zip(a,c):
        waiting = max(0, waiting+int(incoming)-int(slots))
        peak = max(peak, waiting)
    return {"missed_faults": missed, "peak_backlog": peak, "passed": bool(missed <= miss_limit and peak <= backlog_limit)}

