def request_decision(request, allowed, approved, prior):
    def valid(r):
        return (isinstance(r, dict) and set(r) == {"request_id", "asset", "minutes"}
                and all(isinstance(r[k], str) and bool(r[k].strip()) for k in ("request_id", "asset"))
                and type(r["minutes"]) is int and 1 <= r["minutes"] <= 60)
    if not valid(request) or not isinstance(allowed, list) or any(not isinstance(a, str) or not a.strip() for a in allowed) or type(approved) is not bool:
        raise ValueError("Invalid request or permission inputs")
    if prior is not None and (not valid(prior) or prior["request_id"] != request["request_id"]):
        raise ValueError("Prior receipt must belong to this request ID")
    if request["asset"] not in allowed or not approved:
        return "deny"
    if prior is None:
        return "create"
    return "reuse" if prior == request else "conflict"

