def replay(events, limit):
    if type(limit) is not int or limit < 0 or not isinstance(events, list):
        raise ValueError("Invalid replay or limit")
    for event in events:
        if not isinstance(event, dict):
            raise ValueError("Invalid event")
        finish = event == {"action":"finish"}
        tool = set(event) == {"action","status"} and event.get("action") == "tool" and event.get("status") in ("ok","permanent_error")
        if not (finish or tool):
            raise ValueError("Invalid event")
    attempts = 0
    for event in events:
        if event["action"] == "finish":
            return "answer", attempts
        if attempts >= limit:
            return "handoff", attempts
        attempts += 1
        if event["status"] == "permanent_error":
            return "handoff", attempts
    return "handoff", attempts

