def approval_route(proposal, approval, now, permitted):
    if not isinstance(proposal, dict) or not isinstance(approval, dict):
        return "request review"
    keys = ("requestId", "asset", "operation", "revision")
    matches = all(isinstance(proposal.get(k), str) and bool(proposal[k]) and proposal[k] == approval.get(k) for k in keys)
