def resolve_tool(request, allowed, registry):
    if not isinstance(request, dict):
        raise ValueError("Request must be a record")
    for key in ("server", "tool"):
        value = request.get(key)
        if not isinstance(value, str) or not value or "/" in value:
            raise ValueError("Use nonempty names without slashes")
    if not isinstance(allowed, list) or any(not isinstance(x, str) for x in allowed):
        raise ValueError("Allowed endpoints must be a string list")
    if not isinstance(registry, dict) or any(not isinstance(k, str) or not isinstance(v, str) for k,v in registry.items()):
        raise ValueError("Registry must map text names to text labels")
    qualified = request["server"] + "/" + request["tool"]
    if qualified not in allowed:
        return "blocked"
    return registry.get(qualified, "unavailable")

