import math

def score_report(runs, scores, version, rubric):
    if len({r["traceId"] for r in runs}) != len(runs):
        raise ValueError("Duplicate run IDs")
    selected = [r for r in runs if r["promptVersion"] == version]
    if not selected:
        raise ValueError("No selected runs")
    by_id = {}
    for row in scores:
        if row["rubric"] != rubric:
            continue
        key, value = row["traceId"], row["value"]
        if (key in by_id or isinstance(value, bool)
                or not isinstance(value, (int, float))
                or not math.isfinite(value) or not 0 <= value <= 1):
            raise ValueError("Duplicate or invalid selected score")
        by_id[key] = value
    available = [by_id[r["traceId"]] for r in selected if r["traceId"] in by_id]
    mean = sum(available) / len(available) if available else None
    return mean, len(available) / len(selected)

