def contract_report(expected, observed):
    def index(rows):
        result = {}
        for row in rows:
            if row["id"] in result:
                raise ValueError("Duplicate case ID")
            result[row["id"]] = row
        return result
    planned, actual = index(expected), index(observed)
    if actual.keys() - planned.keys():
        raise ValueError("Undeclared case")
    report = {"passed": 0, "failed": 0, "missing": 0}
    for case_id, wanted in planned.items():
        got = actual.get(case_id)
        if got is None:
            report["missing"] += 1
        elif got["tool"] == wanted["tool"] and got["asset"] == wanted["asset"]:
            report["passed"] += 1
        else:
            report["failed"] += 1
    return report

