def paired_changes(before, after):
    def index(rows):
        result = {}
        for row in rows:
            if row["id"] in result or type(row["passed"]) is not bool:
                raise ValueError("Invalid outcome")
            result[row["id"]] = row["passed"]
        return result
    a, b = index(before), index(after)
    if not a or a.keys() != b.keys():
        raise ValueError("Use the same nonempty case set")
    report = {"improved": [], "regressed": [], "unchanged": []}
    for case_id, passed in a.items():
        group = "unchanged" if passed == b[case_id] else "improved" if b[case_id] else "regressed"
        report[group].append(case_id)
    return report

