import math

def release_ready(baseline, candidate, max_ms, min_gain=0):
    def numeric(value, low, high=float("inf")):
        if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value) or not low <= value <= high:
            raise ValueError("Invalid numeric value")
        return value
    def indexed(records, candidate=False):
        if not isinstance(records, list) or not records:
            raise ValueError("Expected a nonempty record list")
        result = {}
        for row in records:
            if not isinstance(row, dict):
                raise ValueError("Expected record dictionaries")
            key = row.get("caseId")
            if not isinstance(key, str) or not key or key in result:
                raise ValueError("Expected unique case IDs")
            numeric(row.get("score"), 0, 1)
            if candidate:
                numeric(row.get("latency"), 0)
                if type(row.get("critical")) is not int or row["critical"] not in {0, 1}:
                    raise ValueError("Invalid critical flag")
            result[key] = row
        return result
    limit = numeric(max_ms, 0)
    minimum = numeric(min_gain, -1, 1)
    old, new = indexed(baseline), indexed(candidate, candidate=True)
    if old.keys() != new.keys():
        raise ValueError("Case sets differ")
    gain = sum(new[key]["score"] - old[key]["score"] for key in old) / len(old)
    return gain >= minimum and all(row["latency"] <= limit and row["critical"] == 0 for row in new.values())

