def trial_decision(required, results, max_ms):
    if type(max_ms) is not int or max_ms < 0 or len(set(required)) != len(required):
        raise ValueError("Invalid requirements")
    indexed = {}
    for row in results:
        if row["id"] in indexed or row["id"] not in required:
            raise ValueError("Unexpected or duplicate result")
        indexed[row["id"]] = row
    reasons = [] if required else ["no required cases"]
    for case_id in required:
        row = indexed.get(case_id)
        if row is None:
            reasons.append(f"{case_id}: missing")
            continue
        if type(row["passed"]) is not bool or type(row["critical"]) is not bool or type(row["ms"]) is not int or row["ms"] < 0:
            raise ValueError("Invalid measurement")
        if not row["passed"]:
            reasons.append(f"{case_id}: task failed")
        if row["critical"]:
            reasons.append(f"{case_id}: critical violation")
        if row["ms"] > max_ms:
            reasons.append(f"{case_id}: too slow")
    return {"decision": "hold" if reasons else "eligible for limited trial", "reasons": reasons}

