import heapq

def shortlist(ids, scores, k):
    heap = []
    for i, score in enumerate(scores):
        item = (score, -i, ids[i])
        if len(heap) < k:
            heapq.heappush(heap, item)
        elif k and item > heap[0]:
            heapq.heapreplace(heap, item)
    return [item[2] for item in sorted(heap, reverse=True)]

