practice.solution:
def order_jobs(dependencies):
    pending = {name:set(needs) for name,needs in dependencies.items()}
    if any(not needs <= pending.keys() for needs in pending.values()):
        raise ValueError("Unknown dependency")
    result = []
    while pending:
        ready = sorted(name for name,needs in pending.items() if not needs)
        if not ready:
            raise ValueError("Cycle")
        name = ready[0]
        result.append(name)
        del pending[name]
        for needs in pending.values():
            needs.discard(name)
    return result

