import itertools

def permutation_failures(predict, names, values, atol):
    baseline=predict(list(names),list(values))
    failures=[]
    for order in itertools.permutations(range(len(names))):
        changed_names=[names[i] for i in order]
        changed_values=[values[i] for i in order]
        if abs(predict(changed_names,changed_values)-baseline)>atol:
            failures.append(changed_names)
    return failures

def positional(names, values):
    return 2*values[0]+10*values[1]

