import copy, json

def ingest_files(previous, discoveries):
    result = copy.deepcopy(previous)
    completed, observed = set(result["checkpoint"]), {}
    for item in discoveries:
        name = item["file"]
        content = json.dumps(item["rows"],sort_keys=True)
        if name in observed and observed[name] != content:
            raise ValueError("Conflicting immutable file")
        observed[name] = content
        if name not in completed:
            result["rows"].extend(copy.deepcopy(item["rows"]))
            result["checkpoint"].append(name)
            completed.add(name)
    return result

