import copy

def apply_changes(state, events):
    result = {row["pump"]:copy.deepcopy(row) for row in state}
    versions = {}
    for row in state + events:
        identity = (row["pump"], row["seq"])
        if identity in versions and versions[identity] != row:
            raise ValueError("Conflicting source version")
        versions[identity] = row
    for row in events:
        old = result.get(row["pump"])
        if old is None or row["seq"] > old["seq"]:
            result[row["pump"]] = copy.deepcopy(row)
    return [result[key] for key in sorted(result)]

