import copy

def publish_candidate(records, minimum, policy, previous):
    if policy not in {"warn","drop","fail"}:
        raise ValueError("Unknown policy")
    accepted = [r for r in records if r["temperature"] is not None and r["temperature"] >= minimum]
    failed = len(records)-len(accepted)
    blocked = policy == "fail" and failed > 0
    result = previous if blocked else accepted if policy == "drop" else records
    return {"status":"failed" if blocked else "published", "rows":copy.deepcopy(result), "passed":len(accepted), "failed":failed}

