def pressure(requests, acknowledged, waiting, arriving, queue_limit):
    released = set(acknowledged)
    held = [row for row in requests if row["state"] != "released" and row["id"] not in released]
    available = queue_limit - len(waiting)
    return {"heldSlots": len(held), "heldBlocks": sum(row["blocks"] for row in held),
            "queued": list(waiting) + list(arriving[:available]), "rejected": list(arriving[available:])}

