import numpy as np

def filter_gaps(initial, displacements, process_variances, observations, measurement_variances):
    n = len(displacements)
    if not (n == len(process_variances) == len(observations) == len(measurement_variances)):
        raise ValueError("Intervals must be aligned")
    mean, variance = map(float, initial)
    states = []
    for move, q, z, r in zip(displacements, process_variances, observations, measurement_variances):
        mean += move
        variance += q
        if not np.all(np.isfinite([mean, variance])):
            raise ValueError("Prediction is outside finite number range")
        if z is not None:
            scale = max(variance, r)
            p, observation = variance / scale, r / scale
            gain, retained = p / (p + observation), observation / (p + observation)
            mean = retained * mean + gain * z
            variance = retained**2 * variance + gain**2 * r
            if not np.all(np.isfinite([mean, variance])):
                raise ValueError("Correction is outside finite number range")
        states.append([mean, variance])
    return np.asarray(states, dtype=float).reshape(n, 2)

