import numpy as np

def separating_experiments(rows, first, second, resolution):
    A = np.asarray(rows,dtype=float)
    a,b = np.asarray(first,dtype=float),np.asarray(second,dtype=float)
    if A.ndim != 2 or min(A.shape) == 0 or a.ndim != 1 or b.shape != a.shape or A.shape[1] != a.size:
        raise ValueError("Incompatible experiment and coefficient shapes")
    if np.ndim(resolution) != 0 or not np.isfinite(A).all() or not np.isfinite(a).all() or not np.isfinite(b).all() or not np.isfinite(resolution) or resolution <= 0:
        raise ValueError("Use finite inputs and positive resolution")
    gaps = np.abs(A @ a - A @ b)
    return np.flatnonzero(gaps >= resolution).tolist()

