import math

def slope_pair(loss, weight, step):
    if not math.isfinite(weight) or not math.isfinite(step) or step <= 0:
        raise ValueError("Use a finite weight and positive finite step")
    lower,centre,upper = (float(loss(point)) for point in (weight-step,weight,weight+step))
    if not all(math.isfinite(value) for value in (lower,centre,upper)):
        raise ValueError("Loss evaluations must be finite")
    return (centre-lower)/step,(upper-centre)/step

