import numpy as np

def directional_check(loss, weights, direction, step):
    w,v = np.asarray(weights,dtype=float),np.asarray(direction,dtype=float)
    if w.ndim != 1 or w.size == 0 or v.shape != w.shape or np.ndim(step) != 0 or not np.isfinite(w).all() or not np.isfinite(v).all() or not np.isfinite(step) or step <= 0:
        raise ValueError("Use compatible finite vectors and a positive step")
    lower,upper = float(loss(w-step*v)),float(loss(w+step*v))
    if not np.isfinite(lower) or not np.isfinite(upper):
        raise ValueError("Loss evaluations must be finite")
    return float((upper-lower)/(2*step))

def loss(w):
    return w[0]**2 + 3*w[1]**2

print(round(directional_check(loss,[2,1],[1,-2],1e-4),6))

